CREATE TABLE public.storage_volume (
    id text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    roles text[] DEFAULT ARRAY['backup'::text] NOT NULL,
    fs_uuid text NOT NULL,
    mount_path text,
    prefix text NOT NULL,
    state text DEFAULT 'absent'::text NOT NULL,
    last_seen_at timestamp with time zone,
    capacity_bytes bigint,
    free_bytes bigint,
    probed_at timestamp with time zone,
    last_ok_at timestamp with time zone,
    last_error text,
    last_error_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT storage_volume_kind_check CHECK ((kind = ANY (ARRAY['internal'::text, 'removable'::text, 'network'::text]))),
    CONSTRAINT storage_volume_roles_check CHECK (((roles <@ ARRAY['backup'::text]) AND (array_length(roles, 1) >= 1))),
    CONSTRAINT storage_volume_state_check CHECK ((state = ANY (ARRAY['present'::text, 'absent'::text, 'degraded'::text])))
);


