    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wiki_articles_refresh_after_new_refs_check CHECK ((refresh_after_new_refs > 0)),
    CONSTRAINT wiki_articles_subject_type_check CHECK ((subject_type = ANY (ARRAY['person'::text, 'place'::text, 'organization'::text, 'day'::text, 'story'::text, 'narrative_identity'::text])))
);


