    epigraph text,
    illustration bytea,
    data_quality jsonb,
    readiness_score integer,
    readiness_details jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    dirty_at timestamp with time zone,
    sources_fingerprint text,
    segmented_at timestamp with time zone,
    narrated_at timestamp with time zone,
    CONSTRAINT wiki_days_last_edited_by_check CHECK ((last_edited_by = ANY (ARRAY['ai'::text, 'human'::text])))
);


--
-- Name: wiki_day_prose; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.wiki_day_prose AS
 SELECT d.id AS day_id,
    d.date,
    NULLIF(TRIM(BOTH FROM p.content), ''::text) AS prose
   FROM ((public.wiki_days d
     LEFT JOIN public.wiki_articles a ON (((a.subject_type = 'day'::text) AND (a.subject_id = d.id))))
     LEFT JOIN public.app_pages p ON ((p.id = a.page_id)));


