CREATE TABLE public.wiki_events (
    id text NOT NULL,
    day_id text NOT NULL,
    started_at timestamp with time zone CONSTRAINT wiki_events_start_time_not_null NOT NULL,
    ended_at timestamp with time zone CONSTRAINT wiki_events_end_time_not_null NOT NULL,
    auto_label text,
    auto_location text,
    user_label text,
    user_location text,
    user_notes text,
    source_ontologies jsonb DEFAULT '[]'::jsonb NOT NULL,
    is_user_added boolean DEFAULT false NOT NULL,
    is_user_edited boolean DEFAULT false NOT NULL,
    user_hidden boolean DEFAULT false NOT NULL,
    user_created boolean DEFAULT false NOT NULL,
    embedding bytea,
    novelty_z double precision,
    topics jsonb DEFAULT '[]'::jsonb NOT NULL,
    entities jsonb DEFAULT '[]'::jsonb NOT NULL,
    topic_novelty jsonb,
    entity_novelty jsonb,
    event_summary text,
    agent_action text,
    avg_hr double precision,
    hr_z double precision,
    hrv_z double precision,
    autonomic_z double precision,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lof_raw double precision,
    local_novelty_z double precision,
    dirty_at timestamp with time zone,
    kind text DEFAULT 'stay'::text NOT NULL,
    is_unknown boolean GENERATED ALWAYS AS ((kind = 'unknown'::text)) STORED NOT NULL,
    is_transit boolean GENERATED ALWAYS AS ((kind = 'transit'::text)) STORED NOT NULL,
    is_sleep boolean GENERATED ALWAYS AS ((kind = 'sleep'::text)) STORED NOT NULL,
    confidence text,
    CONSTRAINT wiki_events_confidence_check CHECK ((confidence = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT wiki_events_kind_check CHECK ((kind = ANY (ARRAY['stay'::text, 'transit'::text, 'sleep'::text, 'unknown'::text])))
);


