--
-- These are NOT schema, and that is exactly why they nearly did not survive.
--
-- The squash is derived from `pg_dump --schema-only`, and the tool proves its
-- result by diffing two schemas — so a migration that INSERTs a row passes the
-- proof and vanishes anyway. Five of the old migrations carried INSERTs; four
-- of these rows are load-bearing, and a box built from a squash without them
-- comes up with no owner, no profile, and no BM25 statistics row.
--
-- Caught by one test (`the_self_person_cannot_be_deleted`), which failed
-- because the owner it protects did not exist. Every other test passed.
--
-- The three singletons share the same constant UUID deliberately: this is a
-- single-household box, the tables carry CHECK constraints pinning them to that
-- id, and code reads them by it rather than by a lookup.
--
-- `ON CONFLICT DO NOTHING` throughout: first boot runs migrations against a
-- database that may already have been seeded by an earlier partial run.

INSERT INTO app_auth_user (id) VALUES ('00000000-0000-0000-0000-000000000001')
    ON CONFLICT (id) DO NOTHING;

INSERT INTO app_user_profile (id) VALUES ('00000000-0000-0000-0000-000000000001')
    ON CONFLICT (id) DO NOTHING;

INSERT INTO app_assistant_profile (id) VALUES ('00000000-0000-0000-0000-000000000001')
    ON CONFLICT (id) DO NOTHING;

-- The BM25 corpus statistics row (n_docs, sum_len). The indexer UPDATEs it; a
-- missing row means the update matches nothing and every BM25 score is computed
-- against a zero corpus.
INSERT INTO search_index_meta (singleton) VALUES (TRUE)
    ON CONFLICT DO NOTHING;
